// Bundled Fluent Emoji illustrations (MIT, Microsoft), generated by `npm run illustrations`.
const files = import.meta.glob('../assets/illustrations/*.svg', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

const byKey = new Map(
  Object.entries(files).map(([file, url]) => [file.slice(file.lastIndexOf('/') + 1, -'.svg'.length), url]),
);

/** Codepoints joined by "-", without the FE0F variation selector, e.g. "2600" for ☀️. */
export function emojiKey(emoji: string): string {
  return [...emoji]
    .map((char) => (char.codePointAt(0) ?? 0).toString(16))
    .filter((code) => code !== 'fe0f')
    .join('-');
}

/** URL of the bundled illustration for an emoji, or undefined when there is none. */
export function illustrationFor(emoji: string): string | undefined {
  return byKey.get(emojiKey(emoji));
}
